// Allocate a writable gsapi_revision_t and choose a length to exercise both success and "size-needed" paths.
// pr must be valid and len should be the size of the structure we provide (or smaller to trigger size-needed).
gsapi_revision_t *pr = new gsapi_revision_t();
// Randomly choose between exact size and a smaller size to explore return behaviors while keeping pr large enough.
unsigned int choice = *FUZZ_PARAM(unsigned int);
int len = (choice % 2 == 0) ? (int)sizeof(gsapi_revision_t) : (int)(sizeof(gsapi_revision_t) / 2);
// Call target
int rc = gsapi_revision(pr, len);
// rc == 0 means success; rc > 0 means required size. Both are acceptable here; treat negatives as bail (should not occur for this API).
if (rc < 0) { FUZZ_BAIL(); }
// Provide pr as an output object (contains product/copyright pointers owned by GS; we do not free them).

// Create a new Ghostscript instance. pinstance must be non-NULL; caller_handle may be any opaque pointer.
void *instance = nullptr;
void *caller_handle = nullptr; // Use nullptr as a benign opaque handle.
int rc = gsapi_new_instance(&instance, caller_handle);
// On some builds, a second instance may fail; ensure contract: failure sets *pinstance to NULL.
if (rc < 0) {
    if (instance != nullptr) { FUZZ_BAIL(); }
    // Do not output an instance on failure (runtime ignores absent outputs implicitly by our not adding them).
    // But harness requires an output variable; enforce creation-only if success.
    FUZZ_BAIL();
}
// Success: instance must be non-null.
if (!instance) { FUZZ_BAIL(); }
// Track lifecycle and configuration state.
FUZZ_SET_ATTR_INT(instance, "inited", 0);
FUZZ_SET_ATTR_INT(instance, "run_begun", 0);
FUZZ_SET_ATTR_INT(instance, "must_exit", 0);
FUZZ_SET_ATTR_INT(instance, "forbid_exit", 0);
FUZZ_SET_ATTR_INT(instance, "stdio_set", 0);
FUZZ_SET_ATTR_PTR(instance, "callout_fn", nullptr);
FUZZ_SET_ATTR_PTR(instance, "callout_handle", nullptr);

// Deletion requires a valid instance that is not in a begun run and, if initialised, must have been cleanly exited.
int run_begun = FUZZ_GET_ATTR_INT(instance, "run_begun");
if (run_begun) { FUZZ_BAIL(); }
int must_exit = FUZZ_GET_ATTR_INT(instance, "must_exit");
if (must_exit) { FUZZ_BAIL(); }
// Proceed with deletion. After this, instance must not be used (runtime will drop it since we don't return it).
gsapi_delete_instance(instance);

// Must be called before initialisation for consistent behaviour.
if (FUZZ_GET_ATTR_INT(instance, "inited")) { FUZZ_BAIL(); }
// Define simple non-blocking callbacks as non-capturing lambdas convertible to function pointers.
auto in_cb  = +[](void *caller_handle, char *buf, int len) -> int {
    // Simulate EOF or provide a few bytes deterministically to avoid blocking.
    if (len <= 0) return -1;
    int provide = len > 0 ? (len < 4 ? len : 4) : 0;
    for (int i = 0; i < provide; ++i) buf[i] = (char)('A' + (i % 26));
    return provide; // 0 can indicate EOF; small positive exercises normal path.
};
auto out_cb = +[](void *caller_handle, const char *str, int len) -> int {
    // Pretend we consumed all bytes.
    return (len < 0) ? 0 : len;
};
auto err_cb = +[](void *caller_handle, const char *str, int len) -> int { return (len < 0) ? 0 : len; };
int rc = gsapi_set_stdio(instance, in_cb, out_cb, err_cb);
if (rc < 0) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT(instance, "stdio_set", 1);

// Must be called before initialisation for consistent behaviour.
if (FUZZ_GET_ATTR_INT(instance, "inited")) { FUZZ_BAIL(); }
// Provide explicit handle distinct from new_instance default; nullptr is acceptable, but vary it slightly.
void *caller_handle = (void*)0x1; // benign opaque token
auto in_cb  = +[](void *caller_handle, char *buf, int len) -> int {
    if (len <= 0) return -1;
    int provide = len > 0 ? (len < 8 ? len : 8) : 0;
    for (int i = 0; i < provide; ++i) buf[i] = (char)('\n');
    return provide;
};
auto out_cb = +[](void *caller_handle, const char *str, int len) -> int { return (len < 0) ? 0 : len; };
auto err_cb = +[](void *caller_handle, const char *str, int len) -> int { return (len < 0) ? 0 : len; };
int rc = gsapi_set_stdio_with_handle(instance, in_cb, out_cb, err_cb, caller_handle);
if (rc < 0) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT(instance, "stdio_set", 1);

// Register a fast poll callback. Effective only if built with CHECK_INTERRUPTS; harmless otherwise.
auto poll_cb = +[](void *caller_handle) -> int {
    // Always continue to avoid aborting runs from inside the harness.
    return 0; // negative would request abort
};
int rc = gsapi_set_poll(instance, poll_cb);
if (rc < 0) { FUZZ_BAIL(); }

// Register poll callback with explicit handle.
void *caller_handle = (void*)0x2;
auto poll_cb = +[](void *caller_handle) -> int { return 0; };
int rc = gsapi_set_poll_with_handle(instance, poll_cb, caller_handle);
if (rc < 0) { FUZZ_BAIL(); }

// Register a callout; store the exact function pointer and handle on the instance for later deregistration.
void *callout_handle = (void*)0xC0110; // opaque token
auto callout = +[](void *instance, void *h, const char *device_name, int id, int size, void *data) -> int {
    // Return 0 (claimed) for even ids, -1 (unclaimed) for odd to exercise both paths.
    return (id % 2 == 0) ? 0 : -1;
};
int rc = gsapi_register_callout(instance, callout, callout_handle);
if (rc < 0) { FUZZ_BAIL(); }
// Track for deregistration.
FUZZ_SET_ATTR_PTR(instance, "callout_fn", (void*)callout);
FUZZ_SET_ATTR_PTR(instance, "callout_handle", callout_handle);

// Retrieve previously registered callout; must match to deregister.
void *fn  = FUZZ_GET_ATTR_PTR(instance, "callout_fn");
void *hdl = FUZZ_GET_ATTR_PTR(instance, "callout_handle");
if (!fn) { FUZZ_BAIL(); }
// Cast back to gs_callout type and deregister.
gs_callout callout = (gs_callout)fn;
gsapi_deregister_callout(instance, callout, hdl);
// Clear attributes to mark deregistration.
FUZZ_SET_ATTR_PTR(instance, "callout_fn", nullptr);
FUZZ_SET_ATTR_PTR(instance, "callout_handle", nullptr);

// Must be set before interpreter initialisation.
if (FUZZ_GET_ATTR_INT(instance, "inited")) { FUZZ_BAIL(); }
std::string list = FUZZ_PARAM_STR();
// Ensure non-empty and space-separated-ish content for coverage.
if (list.empty()) list = "display x11alpha bbox";
int rc = gsapi_set_default_device_list(instance, list.c_str(), (int)list.size());
if (rc < 0) { FUZZ_BAIL(); }

// Retrieve current default device list. Lifetime of returned string is managed by GS.
char *out_list = nullptr;
int out_len = 0;
int rc = gsapi_get_default_device_list(instance, &out_list, &out_len);
if (rc < 0) { FUZZ_BAIL(); }
// Do not free out_list; it is managed by GS.

// encoding must be one of the defined constants {0,1,2}.
int enc = (int)(*FUZZ_PARAM(unsigned int) % 3); // 0=LOCAL,1=UTF8,2=UTF16LE
int rc = gsapi_set_arg_encoding(instance, enc);
if (rc < 0) { FUZZ_BAIL(); }

// Must be called once before running. Provide a small argv vector.
// Bail if already initialised to respect typical lifecycle.
if (FUZZ_GET_ATTR_INT(instance, "inited")) { FUZZ_BAIL(); }
// Build up to 6 args within size limits. argv[0] is conventionally program name.
const int max_args = 1 + (int)(*FUZZ_PARAM(unsigned int) % 5); // 1..5 extra args
static const char *fixed0 = "gs-fuzz";
std::vector<std::string> storage; storage.reserve(max_args + 1);
storage.emplace_back(fixed0);
for (int i = 0; i < max_args; ++i) {
    std::string s = FUZZ_PARAM_STR();
    if (s.size() > 256) s.resize(256); // keep small
    storage.push_back(std::move(s));
}
std::vector<char*> argv; argv.reserve(storage.size());
for (auto &s : storage) argv.push_back(const_cast<char*>(s.c_str()));
int argc = (int)argv.size();
int rc = gsapi_init_with_args(instance, argc, argv.data());
// Track interpreter state per documented rules.
if (rc == 0) {
    FUZZ_SET_ATTR_INT(instance, "inited", 1);
    FUZZ_SET_ATTR_INT(instance, "must_exit", 1);
    FUZZ_SET_ATTR_INT(instance, "forbid_exit", 0);
} else if (rc <= -100) {
    // Quit/fatal: next call must be gsapi_exit(). Mark that an exit is required.
    FUZZ_SET_ATTR_INT(instance, "inited", 1);
    FUZZ_SET_ATTR_INT(instance, "must_exit", 1);
} else if (rc > 0) {
    // Info condition: usage info was produced; do not call exit.
    FUZZ_SET_ATTR_INT(instance, "inited", 0);
    FUZZ_SET_ATTR_INT(instance, "forbid_exit", 1);
} else {
    // Other negative error: treat as bail to avoid undefined lifecycle.
    FUZZ_BAIL();
}

// Must be initialised before running; also no nested begin.
if (!FUZZ_GET_ATTR_INT(instance, "inited")) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(instance, "run_begun")) { FUZZ_BAIL(); }
int exit_code = 0;
int user_errors = (int)(*FUZZ_PARAM(unsigned int) & 1);
int rc = gsapi_run_string_begin(instance, user_errors, &exit_code);
if (rc <= -100) { FUZZ_SET_ATTR_INT(instance, "must_exit", 1); }
if (rc < 0 && rc > -100) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT(instance, "run_begun", 1);

// Must follow a successful begin.
if (!FUZZ_GET_ATTR_INT(instance, "run_begun")) { FUZZ_BAIL(); }
std::string chunk = FUZZ_PARAM_STR();
if (chunk.size() > 512) chunk.resize(512);
int exit_code = 0;
unsigned int length = (unsigned int)chunk.size();
int user_errors = (int)(*FUZZ_PARAM(unsigned int) & 1);
int rc = gsapi_run_string_continue(instance, chunk.data(), length, user_errors, &exit_code);
if (rc <= -100) { FUZZ_SET_ATTR_INT(instance, "must_exit", 1); }
// Normal continuation often returns gs_error_NeedInput (>0). Accept any non-fatal value.
if (rc < 0 && rc > -100) { FUZZ_BAIL(); }

// Must match a prior begin.
if (!FUZZ_GET_ATTR_INT(instance, "run_begun")) { FUZZ_BAIL(); }
int exit_code = 0;
int user_errors = (int)(*FUZZ_PARAM(unsigned int) & 1);
int rc = gsapi_run_string_end(instance, user_errors, &exit_code);
if (rc <= -100) { FUZZ_SET_ATTR_INT(instance, "must_exit", 1); }
if (rc < 0 && rc > -100) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT(instance, "run_begun", 0);

// Requires initialised interpreter.
if (!FUZZ_GET_ATTR_INT(instance, "inited")) { FUZZ_BAIL(); }
std::string s = FUZZ_PARAM_STR();
if (s.size() > 1024) s.resize(1024);
int exit_code = 0;
int user_errors = (int)(*FUZZ_PARAM(unsigned int) & 1);
int rc = gsapi_run_string_with_length(instance, s.data(), (unsigned int)s.size(), user_errors, &exit_code);
if (rc <= -100) { FUZZ_SET_ATTR_INT(instance, "must_exit", 1); }
if (rc < 0 && rc > -100) { FUZZ_BAIL(); }

// Requires initialised interpreter.
if (!FUZZ_GET_ATTR_INT(instance, "inited")) { FUZZ_BAIL(); }
std::string s = FUZZ_PARAM_STR();
// Ensure NUL-terminated semantics by using c_str().
int exit_code = 0;
int user_errors = (int)(*FUZZ_PARAM(unsigned int) & 1);
int rc = gsapi_run_string(instance, s.c_str(), user_errors, &exit_code);
if (rc <= -100) { FUZZ_SET_ATTR_INT(instance, "must_exit", 1); }
if (rc < 0 && rc > -100) { FUZZ_BAIL(); }

// Requires initialised interpreter. Use FUZZ_PARAM_FILENAME to supply a file path.
if (!FUZZ_GET_ATTR_INT(instance, "inited")) { FUZZ_BAIL(); }
const char *path = FUZZ_PARAM_FILENAME();
int exit_code = 0;
int user_errors = (int)(*FUZZ_PARAM(unsigned int) & 1);
int rc = gsapi_run_file(instance, path, user_errors, &exit_code);
if (rc <= -100) { FUZZ_SET_ATTR_INT(instance, "must_exit", 1); }
if (rc < 0 && rc > -100) { FUZZ_BAIL(); }

// Enforce lifecycle: do not call exit when explicitly forbidden (e.g., after Info condition).
if (FUZZ_GET_ATTR_INT(instance, "forbid_exit")) { FUZZ_BAIL(); }
// Typically exit is required after a successful/partial init or fatal quit condition.
int must_exit = FUZZ_GET_ATTR_INT(instance, "must_exit");
if (!must_exit && !FUZZ_GET_ATTR_INT(instance, "inited")) {
    // Not initialised and not required to exit; avoid undefined lifecycle.
    FUZZ_BAIL();
}
int rc = gsapi_exit(instance);
// rc is a Ghostscript status code; negative values indicate errors, but exit may still conclude the session.
// We don't bail on rc as the API can return various statuses here.
// Clear interpreter state to reflect shutdown.
FUZZ_SET_ATTR_INT(instance, "inited", 0);
FUZZ_SET_ATTR_INT(instance, "must_exit", 0);
FUZZ_SET_ATTR_INT(instance, "run_begun", 0);
FUZZ_SET_ATTR_INT(instance, "forbid_exit", 0);

// Set a parameter by name with a typed value. This can be called before or after init.
// Generate a key name (ensure non-empty, NUL-terminated by c_str()).
std::string key = FUZZ_PARAM_STR();
if (key.empty()) key = "PageSize"; // common parameter as fallback
// Choose a type and construct compatible storage. Optionally OR with more_to_come.
unsigned int pick = *FUZZ_PARAM(unsigned int);
int use_more = (pick & 1) ? (int)gs_spt_more_to_come : 0;
int base = (int)((pick >> 1) % 9); // 0..8 maps to enum range
int chosen_type = 0;
const void *value_ptr = nullptr;
// Small local storage for numeric types
bool bval = (bool)((pick >> 5) & 1);
int  ival = (int)(pick & 0x7fff);
float fval = (float)((int)(pick) % 1000) / 10.0f;
long lval = (long)((int)(pick) % 100000);
long long i64val = (long long)((long long)(pick) << 32) | pick;
size_t zval = (size_t)(pick % 4096);
std::string sval = FUZZ_PARAM_STR(); if (sval.size() > 256) sval.resize(256);
char *parsed = const_cast<char*>(sval.data()); // for gs_spt_parsed, pointer to char*
char *name_str = const_cast<char*>(sval.c_str());
char *str_str  = const_cast<char*>(sval.c_str());
char *parsed_holder = parsed; // pointer to char*
switch (base) {
    case 0: chosen_type = gs_spt_bool;   value_ptr = &bval; break;
    case 1: chosen_type = gs_spt_int;    value_ptr = &ival; break;
    case 2: chosen_type = gs_spt_float;  value_ptr = &fval; break;
    case 3: chosen_type = gs_spt_name;   value_ptr = name_str; break;
    case 4: chosen_type = gs_spt_string; value_ptr = str_str; break;
    case 5: chosen_type = gs_spt_long;   value_ptr = &lval; break;
    case 6: chosen_type = gs_spt_i64;    value_ptr = &i64val; break;
    case 7: chosen_type = gs_spt_size_t; value_ptr = &zval; break;
    case 8: default: chosen_type = gs_spt_parsed; value_ptr = &parsed_holder; break;
}
int type_bits = chosen_type | use_more;
// Invoke API; negative return just reflects parameter validation, not a harness violation.
int rc = gsapi_set_param(instance, key.c_str(), value_ptr, (gs_set_param_type)type_bits);
(void)rc;

// Retrieve a parameter: choose a key and a type, handle sizing rules for strings/names/parsed.
std::string key = FUZZ_PARAM_STR();
if (key.empty()) key = "HWResolution"; // common parameter for coverage
unsigned int pick = *FUZZ_PARAM(unsigned int);
int base = (int)(pick % 9);
int chosen_type = 0;
// First, optionally query size requirement with value=NULL.
int required = gsapi_get_param(instance, key.c_str(), nullptr, (gs_set_param_type)base);
if (required > 2048) required = 2048; // cap allocation size for fuzzer performance
if (base == gs_spt_name || base == gs_spt_string || base == gs_spt_parsed) {
    // Two-step for string-like types when size is provided.
    int size = (required > 0) ? required : 64; // fallback small buffer if not provided
    if (size < 2) size = 2;
    std::vector<char> buf((size_t)size, 0);
    void *valptr = (base == gs_spt_parsed) ? (void*)&buf[0] : (void*)&buf[0];
    int rc = gsapi_get_param(instance, key.c_str(), valptr, (gs_set_param_type)base);
    (void)rc; // may be negative (e.g., undefined), which is acceptable
} else {
    // Numeric/binary types: provide appropriately sized storage.
    bool bval = false; int ival = 0; float fval = 0.0f; long lval = 0; long long i64val = 0; size_t zval = 0;
    void *valptr = nullptr;
    switch (base) {
        case gs_spt_bool:   valptr = &bval; break;
        case gs_spt_int:    valptr = &ival; break;
        case gs_spt_float:  valptr = &fval; break;
        case gs_spt_long:   valptr = &lval; break;
        case gs_spt_i64:    valptr = &i64val; break;
        case gs_spt_size_t: valptr = &zval; break;
        default: valptr = &ival; base = gs_spt_int; break;
    }
    int rc = gsapi_get_param(instance, key.c_str(), valptr, (gs_set_param_type)base);
    (void)rc;
}

// Enumerate parameters using an iterator the API updates in place.
void *it = nullptr;
const char *key = nullptr;
gs_set_param_type type = gs_spt_invalid;
// Iterate a small bounded number of steps to avoid long loops.
for (int i = 0; i < 5; ++i) {
    int rc = gsapi_enumerate_params(instance, &it, &key, &type);
    if (rc == 1) { // no more
        break;
    }
    if (rc < 0) {
        // Enumeration error is acceptable (e.g., instance state); stop without bailing.
        break;
    }
    // key is transient; don't store or use after next call.
}

// Add a permitted path for one of the control types.
int type = (int)(*FUZZ_PARAM(unsigned int) % 3); // 0..2
std::string path = FUZZ_PARAM_STR();
if (path.empty()) path = "/tmp"; // ensure non-empty path
int rc = gsapi_add_control_path(instance, type, path.c_str());
// Track count per type for potential later removes (non-fatal if API rejects).
int count_key = FUZZ_GET_ATTR_INT(instance, (type==0?"pc_r_cnt":(type==1?"pc_w_cnt":"pc_c_cnt")));
if (rc >= 0) {
    count_key += 1;
}
FUZZ_SET_ATTR_INT(instance, (type==0?"pc_r_cnt":(type==1?"pc_w_cnt":"pc_c_cnt")), count_key);

// Remove a permitted path from the selected set. The API may return an error if not present; do not treat as a harness failure.
int type = (int)(*FUZZ_PARAM(unsigned int) % 3);
std::string path = FUZZ_PARAM_STR();
if (path.empty()) path = "/tmp";
int rc = gsapi_remove_control_path(instance, type, path.c_str());
// Best-effort decrement on success to keep rough accounting.
if (rc >= 0) {
    const char *k = (type==0?"pc_r_cnt":(type==1?"pc_w_cnt":"pc_c_cnt"));
    int cnt = FUZZ_GET_ATTR_INT(instance, k);
    if (cnt > 0) cnt -= 1;
    FUZZ_SET_ATTR_INT(instance, k, cnt);
}

// Purge all paths for a given type.
int type = (int)(*FUZZ_PARAM(unsigned int) % 3);
gsapi_purge_control_paths(instance, type);
// Reset our tracked counters for that type.
FUZZ_SET_ATTR_INT(instance, (type==0?"pc_r_cnt":(type==1?"pc_w_cnt":"pc_c_cnt")), 0);

// Enable or disable path control.
int enable = (int)(*FUZZ_PARAM(unsigned int) & 1);
gsapi_activate_path_control(instance, enable);
FUZZ_SET_ATTR_INT(instance, "path_control_active", enable ? 1 : 0);

// Query active state; store it for potential cross-checks.
int active = gsapi_is_path_control_active(instance);
FUZZ_SET_ATTR_INT(instance, "path_control_active", active ? 1 : 0);

// Remove a previously added filesystem provider. Must match secret and fs.
int reg = FUZZ_GET_ATTR_INT(fs, "fs_registered");
if (!reg) { FUZZ_BAIL(); }
void *secret = FUZZ_GET_ATTR_PTR(fs, "fs_secret");
if (!secret) { FUZZ_BAIL(); }
// Invoke removal. API is void; assume success if it returns.
gsapi_remove_fs(instance, fs, secret);
// Mark as unregistered so double-remove is prevented by our harness.
FUZZ_SET_ATTR_INT(fs, "fs_registered", 0);

// Build a filesystem provider with safe, fast callbacks respecting buffer sizes.
// Allocate the vtable structure that the host owns; lifetime is managed by the fuzzer pool via outputs.
gsapi_fs_t *fs = new gsapi_fs_t();
void *secret = (void*)0xF5ECE37; // opaque cookie; stable and non-null

// Define minimal callbacks that do not block and respect size contracts.
auto cb_open_file = +[](const gs_memory_t *mem, void *secret, const char *fname, const char *mode, gp_file **file) -> int {
    // Contract: set *file on success; we always fail safely to avoid external I/O.
    if (!file) return -1; // generic error
    *file = nullptr;
    return -21; // gs_error_undefined (benign failure)
};
auto cb_open_pipe = +[](const gs_memory_t *mem, void *secret, const char *fname, char *rfname, const char *mode, gp_file **file) -> int {
    if (!file) return -1;
    *file = nullptr;
    // rfname is caller-provided 4096-byte buffer; we avoid writing beyond the first byte.
    if (rfname) { rfname[0] = '\0'; }
    return -21;
};
auto cb_open_scratch = +[](const gs_memory_t *mem, void *secret, const char *prefix, char *rfname, const char *mode, int rm, gp_file **file) -> int {
    if (!file) return -1;
    *file = nullptr;
    if (rfname) { rfname[0] = '\0'; }
    return -21;
};
auto cb_open_printer = +[](const gs_memory_t *mem, void *secret, char *fname, int binary, gp_file **file) -> int {
    if (!file) return -1;
    *file = nullptr;
    if (fname) { fname[0] = '\0'; }
    return -21;
};
auto cb_open_handle = +[](const gs_memory_t *mem, void *secret, char *fname, const char *mode, gp_file **file) -> int {
    if (!file) return -1;
    *file = nullptr;
    if (fname) { fname[0] = '\0'; }
    return -21;
};

// Populate the vtable.
fs->open_file = cb_open_file;
fs->open_pipe = cb_open_pipe;
fs->open_scratch = cb_open_scratch;
fs->open_printer = cb_open_printer;
fs->open_handle = cb_open_handle;

// Register with Ghostscript; negative return means rejection (e.g., platform policy), not a harness error.
int rc = gsapi_add_fs(instance, fs, secret);
if (rc < 0) {
