import random
import itertools

# This generator produces interesting, valid parameter key names and paired
# values encoded into one buffer. The fuzzer stubs use FUZZ_PARAM_STR for the
# key and value strings. We therefore place two NUL-terminated strings back to
# back: key\0value\0. The stubs may also use the same bytes for numeric types;
# we keep values textual so gsapi can often parse them for gs_spt_parsed/name.
# Buffer size is bounded under 4096 bytes per requirements.

COMMON_KEYS = [
    # Device selection and output
    "OutputFile", "Device", "NOPAUSE", "QUIET",
    # Page geometry
    "PageSize", "PageSize[0]", "PageSize[1]", "HWResolution", "HWSize",
    "Margins", "ImageableArea", "Orientation",
    # Color / rendering
    "BitsPerPixel", "BitsPerComponent", "ColorConversionStrategy",
    "ICCProfile", "ProcessColorModel", "GrayValues",
    # PDF/PS specific
    "PDFSettings", "CompatibilityLevel", "SubsetFonts", "EmbedAllFonts",
    "MaxBitmap", "MaxPatternBitmap", "Overprint",
    # Raster and anti-alias
    "TextAlphaBits", "GraphicsAlphaBits", "BandBufferSpace",
    # Memory / limits
    "MaxStdIO", "MaxFormCache", "MaxLocalVM", "MaxGlobalVM",
    # Path control (stringy params frequently queried)
    "PermitFileReading", "PermitFileWriting", "PermitFileControl",
    # Useful fallbacks used by stub defaults
    "PageSize", "HWResolution"
]

# Some typical values for various types
BOOL_VALUES = ["true", "false", "1", "0"]
INT_VALUES = ["0", "1", "2", "72", "150", "300", "600", "1200", "4096", "65535"]
FLOAT_VALUES = ["0.0", "1.0", "2.54", "72.0", "96.0", "150.0", "300.0", "600.0"]
SIZE_PAIRS = [
    ("PageSize", ["595 842", "612 792", "841 1189", "2480 3508", "2550 3300"]),  # A4, Letter, A0-ish, 300dpi A4, 300dpi Letter
    ("HWResolution", ["72 72", "96 96", "150 150", "300 300", "600 600", "1200 1200"]),
    ("Margins", ["0 0 0 0", "36 36 36 36", "9 9 9 9"]),
]
STRING_VALUES = [
    "default", "", "%stdout", "%stderr", "%pipe%cat", "%handle%1",
    "[ /PageSize [595 842] ] setpagedevice",
    "(Hello) =",
]

NAME_VALUES = [
    "display", "x11", "png16m", "jpeg", "tiff24nc", "bbox", "ps2write", "pdfwrite"
]

# For gs_spt_parsed provide reasonable PostScript snippets
PARSED_SNIPPETS = [
    "<< /PageSize [595 842] >> setpagedevice\n",
    "statusdict /product get ==\n",
    "(Fuzz) print\n",
]

def _rand_choice(rng, seq):
    return seq[rng.randrange(len(seq))]

def _make_key(rng):
    # Bias toward known-good keys while allowing random exploration
    if rng.random() < 0.85:
        key = _rand_choice(rng, COMMON_KEYS)
    else:
        # random ASCII identifier-like string
        letters = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_-[]/"
        ln = rng.randint(3, 24)
        key = ''.join(rng.choice(letters) for _ in range(ln))
    return key

def _make_value_for_key(rng, key):
    # Choose value family based on key patterns
    k = key.lower()
    if "resolution" in k:
        # Select from the HWResolution values
        candidates = []
        for nm, vals in SIZE_PAIRS:
            if nm == "HWResolution":
                candidates = vals
                break
        return _rand_choice(rng, candidates or ["300 300"])
    if "pagesize[0]" in k:
        return _rand_choice(rng, ["595", "612", "841", "2480", "2550"])  # width component
    if "pagesize[1]" in k:
        return _rand_choice(rng, ["842", "792", "1189", "3508", "3300"])  # height component
    if "pagesize" in k or "hwsize" in k or "margins" in k or "imageablearea" in k:
        for nm, vals in SIZE_PAIRS:
            if nm.lower() in k:
                return _rand_choice(rng, vals)
        # fallback to any size pair available
        all_vals = list(itertools.chain.from_iterable(vals for _, vals in SIZE_PAIRS))
        return _rand_choice(rng, all_vals)
    if any(s in k for s in ["alpha", "bits", "max", "vm", "cache", "grayvalues"]):
        return _rand_choice(rng, INT_VALUES)
    if any(s in k for s in ["outputfile", "device", "icc", "profile", "permitfile"]):
        # Strings including special % destinations are often valid
        pool = STRING_VALUES + NAME_VALUES
        return _rand_choice(rng, pool)
    if any(s in k for s in ["overprint", "subset", "embed", "nopause", "quiet"]):
        return _rand_choice(rng, BOOL_VALUES)
    if any(s in k for s in ["color", "level", "orientation", "settings", "model"]):
        pool = NAME_VALUES + STRING_VALUES + INT_VALUES
        return _rand_choice(rng, pool)
    # Fallbacks: prefer a simple scalar or parsed snippet sometimes
    if rng.random() < 0.2:
        return _rand_choice(rng, PARSED_SNIPPETS)
    if rng.random() < 0.4:
        return _rand_choice(rng, FLOAT_VALUES)
    return _rand_choice(rng, INT_VALUES + STRING_VALUES)

def _encode_c_string(s: str) -> bytes:
    # Ensure no interior NULs, keep ASCII/UTF-8 safe, limit to 1023 to stay under cap with pairs
    s = s.replace('\x00', '')
    b = s.encode('utf-8', errors='ignore')[:1023]
    return b + b'\x00'

def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Optionally produce multiple key/value pairs concatenated; the harness may
    # read only the first but other FUZZ_PARAM_STR calls will consume the rest.
    pair_count = 1 + (rng.randrange(3) if rng.random() < 0.6 else 0)

    chunks = []
    for _ in range(pair_count):
        key = _make_key(rng)
        val = _make_value_for_key(rng, key)
        # Occasionally map to parsed snippet to exercise gs_spt_parsed path
        if rng.random() < 0.15:
            val = _rand_choice(rng, PARSED_SNIPPETS)
        chunks.append(_encode_c_string(key))
        chunks.append(_encode_c_string(val))

    buf = b''.join(chunks)
    # Ensure under 4096 bytes
    return buf[:4096]

import os
import random
import string
from typing import List

# Generator for valid filesystem path strings suitable for gsapi_add_control_path/remove_control_path fuzzers.
# We aim to produce NUL-terminated path bytes (C strings). The fuzzing stubs use FUZZ_PARAM_STR() to obtain a path
# and force a non-empty fallback "/tmp" if empty. We'll always return non-empty, valid paths that reference common
# directories or plausible files, covering a range of cases: absolute/relative, with dot segments, spaces, unicode,
# and platform-typical separators. We avoid embedded NULs; terminate with a single NUL at end.

# Notes:
# - The stub modulo-selects a type (0..2) but only needs a string for path. We'll just generate interesting path strings.
# - We keep the size <= 4096 bytes, well below the gp_file_name_sizeof limit mentioned in gsapi_fs_t.


def _rand_seeded_choice(rng: random.Random, seq: List[str]) -> str:
    return seq[rng.randrange(len(seq))]


def _random_ascii_component(rng: random.Random, min_len=1, max_len=12) -> str:
    # Alnum with some safe punctuation often used in filenames
    alphabet = string.ascii_letters + string.digits + "-_.,@# %"
    n = rng.randint(min_len, max_len)
    # Avoid trailing spaces which many filesystems trim; but keep internal spaces
    s = ''.join(rng.choice(alphabet) for _ in range(n)).strip()
    if not s:
        s = "x"
    return s


def _random_unicode_component(rng: random.Random) -> str:
    # Pick from a curated set of common non-ASCII filename characters
    # Keep within BMP and avoid surrogates
    samples = [
        "Δ", "λ", "漢", "字", "み", "ك", "ش", "ä", "ö", "ü", "ß", "ñ", "ç", "ř", "ž", "ø",
        "🙂",  # emoji
        "猫", "文件", "数据",
    ]
    base = _random_ascii_component(rng, 1, 8)
    # Mix a few unicode chars
    uni = ''.join(_rand_seeded_choice(rng, samples) for _ in range(rng.randint(1, 3)))
    # Interleave to keep it readable
    if rng.random() < 0.5:
        return base + uni
    else:
        return uni + base


def _random_extension(rng: random.Random) -> str:
    exts = ["ps", "eps", "pdf", "png", "jpg", "tif", "bmp", "txt", "pfb", "ttf", "otf", "icc"]
    return _rand_seeded_choice(rng, exts)


def _join_path(parts: List[str], sep: str) -> str:
    # Ensure no duplicate separators when joining
    cleaned = []
    for p in parts:
        if p is None:
            continue
        if p == "":
            continue
        cleaned.append(p.strip())
    if not cleaned:
        return sep
    path = cleaned[0]
    for comp in cleaned[1:]:
        if not path.endswith(sep):
            path += sep
        # avoid leading separators in component
        comp = comp.lstrip(sep)
        path += comp
    return path


def _build_unix_path(rng: random.Random) -> str:
    # Common Unix-like bases
    bases = [
        "/tmp", "/var/tmp", "/var/spool/gs", "/home/user", "/usr/local/share/ghostscript", "/dev/null",
        ".", "..",
    ]
    base = _rand_seeded_choice(rng, bases)

    # Decide number of components
    n = rng.randint(0, 4)
    components: List[str] = []
    for _ in range(n):
        choice = rng.random()
        if choice < 0.15:
            components.append(".")
        elif choice < 0.3:
            components.append("..")
        elif choice < 0.55:
            components.append(_random_ascii_component(rng))
        elif choice < 0.8:
            components.append(_random_unicode_component(rng))
        else:
            components.append(_random_ascii_component(rng, 8, 24))

    # Maybe make it a file with extension
    if rng.random() < 0.7:
        leaf = _random_ascii_component(rng, 3, 12)
        if rng.random() < 0.8:
            leaf += "." + _random_extension(rng)
        components.append(leaf)

    # Maybe leading tilde
    if rng.random() < 0.2:
        base = os.path.join("~", base.lstrip("/")) if base.startswith("/") else "~"

    return _join_path([base] + components, "/")


def _build_windows_path(rng: random.Random) -> str:
    # Windows-style paths with backslashes
    drives = ["C:", "D:", "E:"]
    base_choice = rng.random()
    if base_choice < 0.5:
        base = _rand_seeded_choice(rng, drives)
    elif base_choice < 0.8:
        base = r"\\\\?\\C:"  # extended-length prefix
    else:
        base = r"\\\\server\\share"  # UNC share

    n = rng.randint(0, 4)
    components: List[str] = []
    for _ in range(n):
        if rng.random() < 0.7:
            components.append(_random_ascii_component(rng))
        else:
            components.append(_random_unicode_component(rng))

    # Likely file leaf
    if rng.random() < 0.75:
        leaf = _random_ascii_component(rng, 3, 12)
        if rng.random() < 0.8:
            leaf += "." + _random_extension(rng)
        components.append(leaf)

    return _join_path([base] + components, "\\")


def _maybe_trailing_sep(rng: random.Random, path: str) -> str:
    if rng.random() < 0.25:
        # add trailing separator to indicate directory
        if path.startswith("/") or path.startswith("~") or path.startswith("."):
            sep = "/"
        elif path.startswith("\\\\") or (len(path) >= 2 and path[1] == ":"):
            sep = "\\"
        else:
            sep = "/"
        if not path.endswith(sep):
            path += sep
    return path


def _cap_length(path: str, max_bytes: int = 4000) -> str:
    # Ensure UTF-8 encoded length stays within limit (leave room for NUL terminator)
    b = path.encode('utf-8', errors='ignore')
    if len(b) <= max_bytes:
        return path
    # Truncate by bytes safely at codepoint boundary
    truncated = b[:max_bytes]
    # remove dangling partial UTF-8 sequence
    while truncated and (truncated[-1] & 0xC0) == 0x80:
        truncated = truncated[:-1]
    return truncated.decode('utf-8', errors='ignore')


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Decide platform style mix: prefer Unix but include Windows paths often
    if rng.random() < 0.6:
        path = _build_unix_path(rng)
    else:
        path = _build_windows_path(rng)

    # Occasionally produce relative path variants
    rel_mode = rng.random()
    if rel_mode < 0.2:
        # Pure relative
        comps = ["."] + [
            _random_ascii_component(rng) if rng.random() < 0.7 else _random_unicode_component(rng)
            for _ in range(rng.randint(1, 3))
        ]
        # Probably a file
        if rng.random() < 0.8:
            leaf = _random_ascii_component(rng, 3, 10)
            if rng.random() < 0.7:
                leaf += "." + _random_extension(rng)
            comps.append(leaf)
        path = _join_path(comps, "/")
    elif rel_mode < 0.3:
        # Parent-relative
        comps = ["..", _random_ascii_component(rng)]
        path = _join_path(comps, "/")

    # Maybe append trailing separator to hint directory semantics
    path = _maybe_trailing_sep(rng, path)

    # Cap length for safety
    path = _cap_length(path, 4000)

    # Ensure non-empty and valid
    if not path:
        path = "/tmp"

    # Return NUL-terminated UTF-8 bytes
    data = path.encode('utf-8') + b"\x00"
    # Final guard: do not exceed 4096 total
    return data[:4096]
